def restore_pre_direct_death_combat(current: bytes) -> bytes:
    for new, old in EDITS:
        new, old = new.encode("utf-8"), old.encode("utf-8")
        assert current.count(new) == 1, ("A2-P1d combat drift", new[:80])
        current = current.replace(new, old, 1)
    return current
